1	export interface Scenario {
2	  customer: { yearsWithMHPCO: number };
3	  steps: Step[];
4	}
5	
6	export interface QuoteStep {
7	  op: "quote";
8	  items: { type: string; material?: string; enchantment?: number; cursed?: boolean }[];
9	}
10	
11	export type Step = QuoteStep;
12	
13	export interface ScenarioResults {
14	  results: ({ premium: number } | { payout: number; remainingCap: number })[];
15	}
16	
17	const PROCESSING_FEE = 5;
18	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
19	  sword: 100,
20	  amulet: 60,
21	  staff: 80,
22	};
23	const FIRST_INSURANCE_SURCHARGE = 0.1;
24	
25	const roundUpInFavourOfMHPCO = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
26	
27	type Item = QuoteStep["items"][number];
28	
29	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
30	
31	const quotePremium = (step: QuoteStep): number => {
32	  const policyBasePremium = step.items.reduce(
33	    (sum, item) => sum + basePremiumOf(item),
34	    0,
35	  );
36	  return roundUpInFavourOfMHPCO(
37	    policyBasePremium * (1 + FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE,
38	  );
39	};
40	
41	export const runScenario = (scenario: Scenario): ScenarioResults => ({
42	  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
43	});
